// NEON-accelerated inverse DCT64 row and column kernels.
//
// Two independent 64-point inverse DCTs run at once, one in lane 0 and one in
// lane 1 of each 64-bit-element NEON register. The row kernel takes two
// adjacent stride-1 rows and interleaves coefficient index i of each row into
// lanes 0/1; the column kernel takes two adjacent columns of the row-major
// scratch buffer, which already sit in lanes 0/1 of a strided 2-element load.
// Every multiply widens int32->int64 (SMULL/SMLAL), every rounding shift is
// SRSHR and every stage clamp is the CMGT+BSL (BIT/BIF) select, so the
// fixed-point arithmetic, rounding and clamp ranges are bit-for-bit identical
// to the pure-Go inverseDCT64Row / inverseDCT64 references for every supported
// bit depth (8/10/12). This is asserted exhaustively by the row/column dispatch
// differential tests.
//
// The bodies are generated by compiling the equivalent NEON intrinsics (a
// line-by-line transliteration of the pure-Go butterfly, with each cospi
// multiply input narrowed int64->int32 before the widening multiply, which the
// narrowing differential test proves bit-exact) with the system C compiler at
// -O2 and transcribing the disassembly verbatim as WORD-encoded opcodes,
// because Go's arm64 assembler does not expose the signed widening-multiply and
// signed-rounding-shift mnemonics. The I/O is fully unrolled so the bodies are
// pure straight-line leaf code (no branches, no calls); each manages its own
// caller/callee-saved register spill frame below the (empty) Go frame and
// restores every callee-saved register before returning.
//
// SPDX-License-Identifier: BSD-2-Clause
//
// See LICENSE for the BSD-2-Clause grant and NOTICE for the AOM attribution.

//go:build arm64 && !purego

#include "textflag.h"

// func inverseDCT64Row2NEON(r0, r1 *int32, min, max int64)
// Transforms two adjacent stride-1 rows (each >= 64 int32) in place. r0[i] and
// r1[i] occupy lanes 0 and 1. Bit-for-bit identical to inverseDCT64Row run on
// each row.
